def merge_sort(scores):
    if len(scores) <= 1:
        return list(scores)
    mid = len(scores) // 2
    left, right = merge_sort(scores[:mid]), merge_sort(scores[mid:])
    out, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            out.append(left[i])
            i += 1
        else:
            out.append(right[j])
            j += 1
    return out + left[i:] + right[j:]
